def test_sec01_compositional_signed_accepted():
    import hashlib
    import hmac
    key = b'k'
    def sign(body):
        return hmac.new(key, body, hashlib.sha256).hexdigest()
    def verify(body, sig):
        if not sig:
            return False
        return hmac.compare_digest(sign(body), sig)
    body = b'{"a": 1}'
    assert verify(body, sign(body)) is True

def test_sec01_negative_tampered_rejected():
    import hashlib
    import hmac
    key = b'k'
    def sign(body):
        return hmac.new(key, body, hashlib.sha256).hexdigest()
    def verify(body, sig):
        if not sig:
            return False
        return hmac.compare_digest(sign(body), sig)
    assert verify(b'{"a": 2}', sign(b'{"a": 1}')) is False

def test_sec01_boundary_empty_body_rejected():
    import hashlib
    import hmac
    key = b'k'
    def verify(body, sig):
        if not body or not sig:
            return False
        return True
    assert verify(b'', 'sig') is False
    assert verify(b'x', '') is False

def test_sec02_compositional_redacted_echo():
    def handle(payload):
        return {'ok': True, 'echo': payload.get('label')}
    assert handle({'label': 'hi', 'token': 's3cret'}) == {'ok': True, 'echo': 'hi'}

def test_sec02_negative_token_never_echoed():
    def handle(payload):
        return {'ok': True, 'echo': payload.get('label')}
    out = handle({'label': 'hi', 'token': 's3cret'})
    assert 's3cret' not in repr(out)

def test_sec02_boundary_missing_label():
    def handle(payload):
        return {'ok': True, 'echo': payload.get('label')}
    assert handle({}) == {'ok': True, 'echo': None}
